<?php
/** Diagnóstico y reparación conservadora de tablas auxiliares. ELIMINAR tras usar. */
declare(strict_types=1);
session_start();
header('Content-Type: text/html; charset=utf-8');
if (!in_array($_SERVER['REMOTE_ADDR'] ?? '', ['127.0.0.1','::1'], true)) { http_response_code(403); exit('Disponible únicamente en localhost.'); }
if (($_SESSION['rol'] ?? '') !== 'administrador') { http_response_code(403); exit('Inicia sesión como administrador.'); }
if (!isset($_SESSION['token_conexiones'])) $_SESSION['token_conexiones'] = bin2hex(random_bytes(24));
function h($x): string { return htmlspecialchars((string)$x, ENT_QUOTES, 'UTF-8'); }
$logs=[]; $warnings=[]; $errors=[];
try {
 require __DIR__.'/config/conexion_azucreativo.php';
 if (strcasecmp((string)$pdo->query('SELECT DATABASE()')->fetchColumn(),'Azucreativo_db')!==0) throw new RuntimeException('La conexión no apunta a Azucreativo_db.');
 $tables=$pdo->query('SELECT TABLE_NAME,ENGINE FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE()')->fetchAll();
 $known=[];foreach($tables as $t)$known[strtolower($t['TABLE_NAME'])]=$t;
 $getTable=function(string $name) use (&$known): ?string {return $known[strtolower($name)]['TABLE_NAME']??null;};
 $getCols=$pdo->prepare('SELECT COLUMN_NAME,COLUMN_TYPE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND LOWER(TABLE_NAME)=LOWER(?)');
 $col=function(string $t,string $c)use($getCols,$getTable):?string {if(!$getTable($t))return null;$getCols->execute([$t]);foreach($getCols->fetchAll() as $r)if(strcasecmp($r['COLUMN_NAME'],$c)===0)return $r['COLUMN_TYPE'];return null;};
 $type=function(string $t,string $c)use($col):string {$v=$col($t,$c);if(!$v||!preg_match('/^(tinyint|smallint|mediumint|int|bigint)(\(\d+\))?( unsigned)?$/i',$v))throw new RuntimeException("$t.$c no existe o su tipo no es un entero compatible ($v).");return $v;};
 $create=function(string $name,string $sql)use($pdo,&$known,$getTable,&$logs):void {if($getTable($name)){ $logs[]="Existe $name";return;}$pdo->exec($sql);$known[strtolower($name)]=['TABLE_NAME'=>$name,'ENGINE'=>'InnoDB'];$logs[]="Creada $name";};
 $core=[
  'Categoria'=>['ID_Categoria','Nombre'], 'Producto'=>['ID_Producto','Nombre','Precio','Stock'],
  'Cliente'=>['ID_Cliente','Nombre','Apellido'], 'Proveedor'=>['ID_Proveedor'],
  'Inventario'=>['ID_Producto','Cantidad','Fecha_Entrada','Fecha_Salida'],
  'Compra'=>['ID_Compra'], 'Detalle_Compra'=>['ID_Compra','ID_Producto'],
  'Venta'=>['ID_Venta','ID_Cliente','Metodo_Pago','Estado_Venta','Total','Fecha_Venta'],
  'Detalle_Venta'=>['ID_Venta','ID_Producto','Cantidad','Precio_Unitario','Subtotal']
 ];
 foreach($core as $t=>$cols){if(!$getTable($t)){$errors[]="Falta tabla principal $t: se requiere el esquema original, no se inventó una tabla incompatible.";continue;}foreach($cols as $c)if(!$col($t,$c))$errors[]="Falta columna $t.$c en la estructura actual.";if(strtolower((string)$known[strtolower($t)]['ENGINE'])!=='innodb')$warnings[]="$t no utiliza InnoDB: sus relaciones y transacciones pueden fallar.";}
 if ($_SERVER['REQUEST_METHOD']==='POST') {
  if (!hash_equals($_SESSION['token_conexiones'],(string)($_POST['token']??''))) {http_response_code(403);exit('Token inválido.');}
  // Las tablas auxiliares se crean con el tipo real de la PK referenciada.
  $safe=function(callable $fn,string $name)use(&$warnings):void {try{$fn();}catch(Throwable $e){$warnings[]="$name: ".$e->getMessage();}};
  $safe(function()use($create,$type){$id=$type('Cliente','ID_Cliente');$create('Cliente_Usuario_Web',"CREATE TABLE `Cliente_Usuario_Web` (`ID_Usuario_Login` INT NOT NULL PRIMARY KEY,`ID_Cliente` $id NOT NULL UNIQUE,CONSTRAINT `fk_cuw_cliente` FOREIGN KEY (`ID_Cliente`) REFERENCES `Cliente`(`ID_Cliente`)) ENGINE=InnoDB");},'Relación de clientes web');
  $safe(function()use($create,$type){$id=$type('Venta','ID_Venta');$create('Venta_Cliente_Web',"CREATE TABLE `Venta_Cliente_Web` (`ID_Venta` $id NOT NULL PRIMARY KEY,`ID_Usuario_Login` INT NOT NULL,INDEX `idx_vcw_usuario` (`ID_Usuario_Login`),CONSTRAINT `fk_vcw_venta` FOREIGN KEY (`ID_Venta`) REFERENCES `Venta`(`ID_Venta`)) ENGINE=InnoDB");},'Relación de ventas web');
  $safe(function()use($create){$create('Corte_Caja','CREATE TABLE `Corte_Caja` (`ID_Corte` INT AUTO_INCREMENT PRIMARY KEY,`ID_Usuario` INT NOT NULL,`Fecha_Inicio` DATETIME NOT NULL,`Fecha_Cierre` DATETIME NOT NULL,`Num_Ventas` INT NOT NULL,`Total_Efectivo` DECIMAL(12,2) NOT NULL,`Total_Tarjeta` DECIMAL(12,2) NOT NULL,`Total_Transferencia` DECIMAL(12,2) NOT NULL,`Efectivo_Contado` DECIMAL(12,2) NOT NULL,`Diferencia` DECIMAL(12,2) NOT NULL) ENGINE=InnoDB');},'Cortes de caja');
  $safe(function()use($create,$type){$id=$type('Venta','ID_Venta');$create('Venta_Empleado',"CREATE TABLE `Venta_Empleado` (`ID_Venta` $id NOT NULL PRIMARY KEY,`ID_Usuario` INT NOT NULL,`ID_Corte` INT NULL,INDEX `idx_empleado_corte` (`ID_Usuario`,`ID_Corte`),CONSTRAINT `fk_ve_venta_general` FOREIGN KEY (`ID_Venta`) REFERENCES `Venta`(`ID_Venta`),CONSTRAINT `fk_ve_corte_general` FOREIGN KEY (`ID_Corte`) REFERENCES `Corte_Caja`(`ID_Corte`)) ENGINE=InnoDB");},'Ventas empleados');
  $safe(function()use($create,$type){$id=$type('Corte_Caja','ID_Corte');$create('Auditoria_Corte_Caja',"CREATE TABLE `Auditoria_Corte_Caja` (`ID_Auditoria` INT AUTO_INCREMENT PRIMARY KEY,`ID_Corte` $id NOT NULL,`ID_Admin` INT NOT NULL,`Fecha` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,`Contado_Anterior` DECIMAL(12,2) NOT NULL,`Contado_Nuevo` DECIMAL(12,2) NOT NULL,`Motivo` VARCHAR(500) NOT NULL,INDEX (`ID_Corte`),CONSTRAINT `fk_auditoria_general` FOREIGN KEY (`ID_Corte`) REFERENCES `Corte_Caja`(`ID_Corte`)) ENGINE=InnoDB");},'Auditoría cortes');
  $safe(function()use($create){$create('Pedido_Cliente',"CREATE TABLE `Pedido_Cliente` (`ID_Pedido` INT AUTO_INCREMENT PRIMARY KEY,`ID_Usuario_Login` INT NOT NULL,`Usuario` VARCHAR(100) NOT NULL,`Fecha` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,`Metodo_Pago` ENUM('Efectivo','Tarjeta','Transferencia') NOT NULL,`Estado` ENUM('Pendiente','Confirmado','Cancelado','Entregado') NOT NULL DEFAULT 'Pendiente',`Total` DECIMAL(12,2) NOT NULL) ENGINE=InnoDB");},'Compatibilidad pedidos anteriores');
  $safe(function()use($create,$type){$p=$type('Pedido_Cliente','ID_Pedido');$pr=$type('Producto','ID_Producto');$create('Pedido_Cliente_Detalle',"CREATE TABLE `Pedido_Cliente_Detalle` (`ID_Detalle` INT AUTO_INCREMENT PRIMARY KEY,`ID_Pedido` $p NOT NULL,`ID_Producto` $pr NOT NULL,`Nombre_Producto` VARCHAR(255) NOT NULL,`Cantidad` INT NOT NULL,`Precio_Unitario` DECIMAL(12,2) NOT NULL,`Subtotal` DECIMAL(12,2) NOT NULL,INDEX (`ID_Pedido`),CONSTRAINT `fk_pcd_general` FOREIGN KEY (`ID_Pedido`) REFERENCES `Pedido_Cliente`(`ID_Pedido`)) ENGINE=InnoDB");},'Detalles de pedidos anteriores');
  $safe(function()use($create,$type){$p=$type('Pedido_Cliente','ID_Pedido');$v=$type('Venta','ID_Venta');$create('Pedido_Venta',"CREATE TABLE `Pedido_Venta` (`ID_Pedido` $p NOT NULL PRIMARY KEY,`ID_Venta` $v NOT NULL UNIQUE,CONSTRAINT `fk_pv_pedido_general` FOREIGN KEY (`ID_Pedido`) REFERENCES `Pedido_Cliente`(`ID_Pedido`),CONSTRAINT `fk_pv_venta_general` FOREIGN KEY (`ID_Venta`) REFERENCES `Venta`(`ID_Venta`)) ENGINE=InnoDB");},'Pedidos convertidos a ventas');
 }
 // Revisar tablas auxiliares existentes: CREATE TABLE IF NOT EXISTS no repara columnas ni claves.
 $aux=['Cliente_Usuario_Web'=>['ID_Usuario_Login','ID_Cliente'],'Venta_Cliente_Web'=>['ID_Venta','ID_Usuario_Login'],'Venta_Empleado'=>['ID_Venta','ID_Usuario','ID_Corte'],'Corte_Caja'=>['ID_Corte','ID_Usuario','Fecha_Inicio','Fecha_Cierre','Num_Ventas','Total_Efectivo','Total_Tarjeta','Total_Transferencia','Efectivo_Contado','Diferencia'],'Auditoria_Corte_Caja'=>['ID_Auditoria','ID_Corte','ID_Admin','Fecha','Contado_Anterior','Contado_Nuevo','Motivo'],'Pedido_Cliente'=>['ID_Pedido','ID_Usuario_Login','Usuario','Fecha','Metodo_Pago','Estado','Total'],'Pedido_Cliente_Detalle'=>['ID_Detalle','ID_Pedido','ID_Producto','Nombre_Producto','Cantidad','Precio_Unitario','Subtotal'],'Pedido_Venta'=>['ID_Pedido','ID_Venta']];
 foreach($aux as $t=>$cols){if(!$getTable($t)){$warnings[]="Pendiente tabla $t";continue;}foreach($cols as $c)if(!$col($t,$c))$warnings[]="Falta columna $t.$c; requiere migración específica para preservar datos.";}
 foreach([['Cliente_Usuario_Web','ID_Cliente','Cliente','ID_Cliente'],['Venta_Cliente_Web','ID_Venta','Venta','ID_Venta'],['Venta_Empleado','ID_Venta','Venta','ID_Venta'],['Venta_Empleado','ID_Corte','Corte_Caja','ID_Corte']] as [$child,$cc,$parent,$pc]){
  if(!$col($child,$cc)||!$col($parent,$pc))continue;
  if(strtolower($col($child,$cc))!==strtolower($col($parent,$pc)))$warnings[]="Tipos distintos: $child.$cc (".$col($child,$cc).") y $parent.$pc (".$col($parent,$pc).")";
  $fk=$pdo->prepare('SELECT COUNT(*) FROM information_schema.KEY_COLUMN_USAGE WHERE TABLE_SCHEMA=DATABASE() AND LOWER(TABLE_NAME)=LOWER(?) AND LOWER(COLUMN_NAME)=LOWER(?) AND LOWER(REFERENCED_TABLE_NAME)=LOWER(?) AND LOWER(REFERENCED_COLUMN_NAME)=LOWER(?)');$fk->execute([$child,$cc,$parent,$pc]);if(!(int)$fk->fetchColumn())$warnings[]="Sin clave foránea: $child.$cc → $parent.$pc. Si la tabla ya existía, revisa registros e índices antes de agregarla.";
 }
 try {require __DIR__.'/login/conexion.php';if(strcasecmp((string)$pdo->query('SELECT DATABASE()')->fetchColumn(),'login_db')!==0)$warnings[]='La conexión de usuarios no apunta a login_db.';else { $q=$pdo->query("SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND LOWER(TABLE_NAME)='usuarios' AND LOWER(COLUMN_NAME)='rol'");if(!(int)$q->fetchColumn())$warnings[]='login_db.usuarios no tiene columna rol. Ejecuta la migración de roles tras respaldar.';$logs[]='Conexión a login_db verificada.';}}catch(Throwable $e){$warnings[]='No se pudo verificar login_db: '.$e->getMessage();}
} catch(Throwable $e){$errors[]=$e->getMessage();}
